#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int x[100], y[100];
    for (int i = 0; i < n; i++)
        plik >> x[i] >> y[i];
    int minX = x[0], maxX = x[0], minY = y[0], maxY = y[0];
    for (int i = 1; i < n; i++) {
        if (x[i] < minX) minX = x[i];
        if (x[i] > maxX) maxX = x[i];
        if (y[i] < minY) minY = y[i];
        if (y[i] > maxY) maxY = y[i];
    }
    int pole = (maxX - minX) * (maxY - minY);
    int obwod = 2 * ((maxX - minX) + (maxY - minY));
    int naBrzegu = 0;
    for (int i = 0; i < n; i++) {
        if (x[i] == minX || x[i] == maxX || y[i] == minY || y[i] == maxY)
            naBrzegu++;
    }
    cout << "Bounding box: (" << minX << "," << minY << ") - (" << maxX << "," << maxY << ")" << endl;
    cout << "Pole: " << pole << endl;
    cout << "Obwod: " << obwod << endl;
    cout << "Punkty na brzegu: " << naBrzegu << endl;
    return 0;
}
```

Weryfikacja:
- minX=1, maxX=7, minY=1, maxY=6
- Pole: 6*5=30, Obwod: 2*(6+5)=22
- Na brzegu: (7,1)x=7,y=1; (1,6)x=1,y=6; (6,6)y=6; (4,1)y=1; (1,3)x=1 = 5 punktow
